import { describe, expect, it } from 'vitest'
import { makeQr, maxQrBytes } from './qr'

// Matrices checked against the qrcode library, error level M, for these payloads.
const FIXTURES: Record<string, string> = {
  'https://vibe.j2team.org':
    '',
  'Cà phê':
    '',
}

function pack(modules: boolean[][]): string {
  return modules.map((row) => row.map((cell) => (cell ? '1' : '0')).join('')).join('')
}

describe('makeQr', () => {
  it('matches known matrices, including a Vietnamese payload', () => {
    for (const [text, bits] of Object.entries(FIXTURES)) {
      const grid = makeQr(text)
      expect(pack(grid)).toBe(bits)
      expect(grid).toHaveLength(Math.sqrt(bits.length))
    }
  })

  it('keeps the three finder squares', () => {
    const grid = makeQr('https://vibe.j2team.org')
    const size = grid.length
    expect(grid[0]?.[0]).toBe(true)
    expect(grid[0]?.[size - 1]).toBe(true)
    expect(grid[size - 1]?.[0]).toBe(true)
  })

  it('refuses a payload past version 10', () => {
    expect(() => makeQr('a'.repeat(maxQrBytes() + 1))).toThrow(/byte/)
  })
})
